// Tester authorisation and trial allowances.
//
// The trial has no user accounts yet, so access is possession of a tester code.
// Only the SHA-256 of each code is configured on the server; the code itself is
// never stored or logged. Sessions are random IDs generated by the browser and
// hashed before they reach the database, so usage data is pseudonymous.
import type { D1Database, Env } from './types.ts';

export const SESSION_HEADER = 'x-trial-session';
export const KEY_HEADER = 'x-trial-key';

export interface TrialIdentity {
  /** SHA-256 of the presented access code. Never persisted. */
  keyHash: string;
  /** SHA-256 of the browser session id. Persisted as session_ref. */
  sessionRef: string;
}

export type TrialAuthResult =
  | { ok: true; identity: TrialIdentity }
  | { ok: false; status: number; code: string; message: string };

export interface TrialLimits {
  sessionTurnsPerDay: number;
  sessionCallsPerDay: number;
  globalTurnsPerDay: number;
  globalCallsPerDay: number;
  totalTurns: number;
  totalCalls: number;
  totalTokens: number;
}

export interface UsageCounters {
  sessionCallsToday: number;
  sessionTurnsToday: number;
  globalCallsToday: number;
  globalTurnsToday: number;
  totalCalls: number;
  totalTurns: number;
  totalTokens: number;
}

export type LimitName =
  | 'session_turns_per_day'
  | 'session_calls_per_day'
  | 'global_turns_per_day'
  | 'global_calls_per_day'
  | 'trial_turns'
  | 'trial_calls'
  | 'trial_tokens';

export interface LimitDecision {
  allowed: boolean;
  limit?: LimitName;
  message?: string;
}

const DEFAULT_LIMITS: TrialLimits = {
  sessionTurnsPerDay: 10,
  sessionCallsPerDay: 18,
  globalTurnsPerDay: 30,
  globalCallsPerDay: 50,
  totalTurns: 150,
  totalCalls: 250,
  totalTokens: 400_000,
};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function readLimit(value: string | undefined, fallback: number): number {
  if (typeof value !== 'string' || !value.trim()) return fallback;

  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return fallback;

  return Math.floor(parsed);
}

export function parseTrialLimits(env: Env): TrialLimits {
  return {
    sessionTurnsPerDay: readLimit(
      env.TRIAL_SESSION_TURNS_PER_DAY,
      DEFAULT_LIMITS.sessionTurnsPerDay
    ),
    sessionCallsPerDay: readLimit(
      env.TRIAL_SESSION_CALLS_PER_DAY,
      DEFAULT_LIMITS.sessionCallsPerDay
    ),
    globalTurnsPerDay: readLimit(env.TRIAL_GLOBAL_TURNS_PER_DAY, DEFAULT_LIMITS.globalTurnsPerDay),
    globalCallsPerDay: readLimit(env.TRIAL_GLOBAL_CALLS_PER_DAY, DEFAULT_LIMITS.globalCallsPerDay),
    totalTurns: readLimit(env.TRIAL_TOTAL_TURNS, DEFAULT_LIMITS.totalTurns),
    totalCalls: readLimit(env.TRIAL_TOTAL_CALLS, DEFAULT_LIMITS.totalCalls),
    totalTokens: readLimit(env.TRIAL_TOTAL_TOKENS, DEFAULT_LIMITS.totalTokens),
  };
}

export async function sha256Hex(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest('SHA-256', bytes);

  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function configuredHashes(env: Env): string[] {
  return (env.TRIAL_KEY_HASHES ?? '')
    .split(/[\s,]+/)
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);
}

function hashMatches(candidate: string, configured: readonly string[]): boolean {
  let matched = false;
  for (const hash of configured) {
    if (hash.length !== candidate.length) continue;

    let difference = 0;
    for (let index = 0; index < hash.length; index += 1) {
      difference |= hash.charCodeAt(index) ^ candidate.charCodeAt(index);
    }
    if (difference === 0) matched = true;
  }

  return matched;
}

export async function authoriseTrial(
  headers: Headers,
  env: Env
): Promise<TrialAuthResult> {
  const hashes = configuredHashes(env);
  if (hashes.length === 0) {
    return {
      ok: false,
      status: 503,
      code: 'trial_unconfigured',
      message: 'The Cloudflare trial is not configured with tester access codes.',
    };
  }

  const key = headers.get(KEY_HEADER)?.trim() ?? '';
  if (!key) {
    return {
      ok: false,
      status: 401,
      code: 'trial_auth',
      message: 'Enter the trial access code you were given.',
    };
  }

  const keyHash = await sha256Hex(key);
  if (!hashMatches(keyHash, hashes)) {
    return {
      ok: false,
      status: 401,
      code: 'trial_auth',
      message: 'That trial access code is not recognised.',
    };
  }

  const session = headers.get(SESSION_HEADER)?.trim() ?? '';
  if (!UUID_PATTERN.test(session)) {
    return {
      ok: false,
      status: 400,
      code: 'trial_session',
      message: 'A valid pseudonymous trial session is required.',
    };
  }

  return {
    ok: true,
    identity: { keyHash, sessionRef: await sha256Hex(session.toLowerCase()) },
  };
}

/** UTC midnight, the boundary Cloudflare uses for its daily free allocation. */
export function dayStartIso(now: Date): string {
  return `${now.toISOString().slice(0, 10)}T00:00:00.000Z`;
}

export async function readUsageCounters(
  db: D1Database,
  sessionRef: string,
  sinceIso: string
): Promise<UsageCounters> {
  const sessionRow = await db
    .prepare(
      `SELECT COUNT(*) AS session_calls_today,
              COUNT(DISTINCT turn_id) AS session_turns_today
         FROM generation_attempts
        WHERE session_ref = ?
          AND created_at >= ?`
    )
    .bind(sessionRef, sinceIso)
    .first<{ session_calls_today: number; session_turns_today: number }>();

  const overallRow = await db
    .prepare(
      `SELECT COUNT(*) AS total_calls,
              COUNT(DISTINCT turn_id) AS total_turns,
              COALESCE(SUM(total_tokens), 0) AS total_tokens,
              COALESCE(SUM(CASE WHEN created_at >= ? THEN 1 ELSE 0 END), 0) AS global_calls_today,
              COUNT(DISTINCT CASE WHEN created_at >= ? THEN turn_id END) AS global_turns_today
         FROM generation_attempts`
    )
    .bind(sinceIso, sinceIso)
    .first<{
      total_calls: number;
      total_turns: number;
      total_tokens: number;
      global_calls_today: number;
      global_turns_today: number;
    }>();

  return {
    sessionCallsToday: Number(sessionRow?.session_calls_today ?? 0),
    sessionTurnsToday: Number(sessionRow?.session_turns_today ?? 0),
    globalCallsToday: Number(overallRow?.global_calls_today ?? 0),
    globalTurnsToday: Number(overallRow?.global_turns_today ?? 0),
    totalCalls: Number(overallRow?.total_calls ?? 0),
    totalTurns: Number(overallRow?.total_turns ?? 0),
    totalTokens: Number(overallRow?.total_tokens ?? 0),
  };
}

/**
 * Decide whether one more turn may start. Checks run cheapest-to-explain first:
 * exhausted trial allowances, then shared daily usage, then this session.
 */
export function evaluateLimits(counters: UsageCounters, limits: TrialLimits): LimitDecision {
  if (counters.totalTokens >= limits.totalTokens) {
    return {
      allowed: false,
      limit: 'trial_tokens',
      message:
        'The guided-discovery trial has used its overall token allowance. No more suggestions will be generated.',
    };
  }

  if (counters.totalTurns >= limits.totalTurns) {
    return {
      allowed: false,
      limit: 'trial_turns',
      message: 'The guided-discovery trial has used its overall naming-turn allowance.',
    };
  }

  if (counters.totalCalls >= limits.totalCalls) {
    return {
      allowed: false,
      limit: 'trial_calls',
      message: 'The guided-discovery trial has used its overall provider-call allowance.',
    };
  }

  if (counters.globalCallsToday >= limits.globalCallsPerDay) {
    return {
      allowed: false,
      limit: 'global_calls_per_day',
      message:
        'The shared trial has reached its daily provider-call allowance. It resets at 00:00 UTC.',
    };
  }

  if (counters.globalTurnsToday >= limits.globalTurnsPerDay) {
    return {
      allowed: false,
      limit: 'global_turns_per_day',
      message: 'The shared trial has reached its daily naming-turn allowance. It resets at 00:00 UTC.',
    };
  }

  if (counters.sessionTurnsToday >= limits.sessionTurnsPerDay) {
    return {
      allowed: false,
      limit: 'session_turns_per_day',
      message: `This tester session has used its ${limits.sessionTurnsPerDay} daily naming turns. It resets at 00:00 UTC.`,
    };
  }

  if (counters.sessionCallsToday >= limits.sessionCallsPerDay) {
    return {
      allowed: false,
      limit: 'session_calls_per_day',
      message: `This tester session has used its ${limits.sessionCallsPerDay} daily provider calls. It resets at 00:00 UTC.`,
    };
  }

  return { allowed: true };
}
